import json
def std(k,p,h): return f"<ul><li><strong>Pre koho:</strong> {k}</li><li><strong>Použitie:</strong> {p}</li><li><strong>Hlavné prínosy:</strong> {h}</li></ul>"
R=[]
def add(code,name,desc): R.append({"code":code,"nameSk":name,"descriptionSk":desc})
def air(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("domácnosť, kancelária, kúpeľňa","rozprášiť do vzduchu zo vzdialenosti",f"rýchle osvieženie, príjemná vôňa, {v}"))
def refill(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("domácnosť","vložiť do kompatibilného osviežovača podľa návodu",f"príjemná vôňa, {v}"))
def spray(code,name,lead,h): add(code,name,f"<p>{lead}</p>"+std("domácnosť","rozprášiť do vzduchu",h))
def mouth(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("každodenná ústna hygiena","po čistení zubov vypláchnuť ústa podľa návodu",f"sviežy dych, ústna hygiena, {v}"))
def paste(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("každodenná starostlivosť o chrup","čistiť zuby dvakrát denne",f"starostlivosť o zuby, sviežy dych, {v}"))
def shower(code,name,lead,k,h): add(code,name,f"<p>{lead}</p>"+std(k,"vmasírovať do mokrej pokožky a opláchnuť",h))
def diffuser(code,name,lead,v): add(code,name,f"<p>{lead}</p>"+std("domov, kancelária","umiestniť do miestnosti a prípadne otočiť tyčinky",f"dlhotrvajúca vôňa, {v}"))

