add("1730","The Humble Co. Floss Picks dentálne párátka sviežia mäta 50 ks","<p>Dvojité vlákna s mentolovou príchuťou zaisťujú sviežy dych, rukoväť je z 53 % vyrobená z rastlinných materiálov, bez BPA a PFAS. Schválené zubnými lekármi, balenie je recyklovateľné. Vegánsky produkt šetrný k prírode.\nPoužitie: denne pred čistením zubov jemne pracujte s párátkom medzi každým zubom, posuňte vlákno pozdĺž bočných strán zubov na dôkladné čistenie pod líniou ďasien.</p>")
add("1654","Maui Moisture čistiaci sprchový gél so sopečným popolom 577 ml","<p>Chcete premeniť každodenné sprchovanie na príjemný rituál? Tento detoxikačný sprchový gél s jemnou penivou textúrou účinne odstraňuje nečistoty bez toho, aby pokožku vysúšal. Zo sprchy vyjdete s dokonale čistou, hebkou a krásne navoňanou pokožkou.\nVlastnosti: \n\nčistí a detoxikuje pokožku\nzjemňuje a zvyšuje elasticitu\nobnovuje pocit komfortu\nvytvára bohatú penu\nzanecháva pokožku zamatovo hebkú\n\nZloženie: \n\nvegánsky produkt</p>")
add("1878","Durex Classic Regular Fit 3 ks","<p>Pohodlné nasadenie a strih\nAnatomický tvar Easy‑On uľahčuje nasadenie a zlepšuje prispôsobenie pri bežnom styku. Kondóm je určený pre štandardnú veľkosť, takže sedí väčšine používateľov a znižuje riziko skĺznutia alebo nepohodlia.\nMateriál a overená bezpečnosť\nKondómy sú vyrobené z latexu a každý kus je 100 % elektronicky testovaný. Produkt má zdravotnícku certifikáciu CE, ktorá zaručuje konzistentnú kvalitu a spoľahlivosť pri používaní.\nDiskrétna textúra a bez vône\nPriehľadný a hladký povrch bez príchute poskytuje diskrétny pocit a minimalizuje senzorické vnemy. Produkt je označený ako vhodný pre osoby citlivé na vône, hoci latex môže mať prirodzený zápach.\nBalenie a použitie\nBalíček obsahuje 3 ks v skúšobnom formáte, ideálny na vyskúšanie alebo diskrétne nosenie. Kondóm je určený výlučne na jednorazové použitie — po styku ho vždy zlikvidujte a nepoužívajte znova.</p>")
add("724","Perry Ellis 360° Red 100 ml","<p>Mladistvá vôňa toaletnej vody Perry Ellis 360° Red je určená pre muža, ktorého charizma si ľahko získa srdce nejednej ženy. Pre muža, ktorý je sebavedomý a ide rovno za svojím životným cieľom. Objavte vôňu, ktorá podčiarkne vašu osobnosť a umožní vám žiariť kamkoľvek pôjdete. Orientálne korenistá vôňa bola uvedená v roku 2003 a ponúka voňavú kompozíciu, o ktorej výnimočnosti sa presvedčíte pri prvom privoňaní.\nOrientálne korenistá vôňa\nDynamická vôňa pre mužov sa začína súhrou osviežujúceho mixu ovocia. Mandarínka sa spája s vôňou limetky, bergamotu a pomaranča. Úvodné sviežé tóny dopĺňa ľahko pikantná vôňa klinčeka, muškátového orecha a hrejivá vôňa škorice. V srdci toaletnej vody sa predstavuje koriander a aromatická levanduľa. Voňavý koncert uzatvára vôňa santalového dreva, cédra, vetiveru, pačuli, dubového machu a veľmi zmyselná vôňa pižma.</p>".replace("sviežé","svieže").replace("orecha","orechu"))
add("1698","Dental Delight Shimmery Shine Zubná pasta s aktívnym uhlím 75 ml","<p>Dental Delight Shimmery Shine s aktívnym uhlím je vegánska zubná pasta (75 ml), ktorá čistí zuby a chráni ich pred zubným kazom, usadeninami a zubným kameňom. Neobsahuje mikroplasty.</p>"+std("každodenná starostlivosť o zuby","čistiť zuby dvakrát denne","aktívna formula proti baktériám, bez mikroplastov, vegan, 75 ml"))
